import '../../../core/assets/game_asset_profile.dart';

abstract final class PokemonLearnsetResolver {
  static List<int> tutorMoves(GameAssetProfile profile, int pokemonId) =>
      (_forGame(profile, tutor: true)[pokemonId] ?? const <int>[]);

  static List<int> eggMoves(GameAssetProfile profile, int pokemonId) {
    final baseId = baseSpeciesId(profile, pokemonId);
    return _forGame(profile, tutor: false)[baseId] ?? const <int>[];
  }

  static List<int> eggMoveParents(
    GameAssetProfile profile,
    int pokemonId,
    int moveId,
  ) {
    final baseId = baseSpeciesId(profile, pokemonId);
    final group = _groupForGame(profile);
    return _eggParentsByGroup[group]?[baseId]?[moveId] ?? const <int>[];
  }

  static int baseSpeciesId(GameAssetProfile profile, int pokemonId) {
    final maximumId = switch (profile.game) {
      PokemonAssetGame.redBlue || PokemonAssetGame.yellow => 151,
      PokemonAssetGame.gold ||
      PokemonAssetGame.silver ||
      PokemonAssetGame.crystal => 251,
      PokemonAssetGame.rubySapphire ||
      PokemonAssetGame.emerald ||
      PokemonAssetGame.fireRedLeafGreen => 386,
      _ => 0,
    };
    var current = pokemonId;
    while (true) {
      final parent = _parentSpecies[current];
      if (parent == null || parent > maximumId) return current;
      current = parent;
    }
  }

  static Map<int, List<int>> _forGame(GameAssetProfile profile, {required bool tutor}) {
    final group = _groupForGame(profile);
    return (tutor ? _tutorByGroup : _eggByGroup)[group] ?? const <int, List<int>>{};
  }

  static int _groupForGame(GameAssetProfile profile) => switch (profile.game) {
      PokemonAssetGame.redBlue => 1,
      PokemonAssetGame.yellow => 2,
      PokemonAssetGame.gold || PokemonAssetGame.silver => 3,
      PokemonAssetGame.crystal => 4,
      PokemonAssetGame.rubySapphire => 5,
      PokemonAssetGame.emerald => 6,
      PokemonAssetGame.fireRedLeafGreen => 7,
      _ => 0,
    };

  static const Map<int, Map<int, List<int>>> _tutorByGroup = <int, Map<int, List<int>>>{
